INSERT INTO `custom_dictionary` VALUES (1,'사틴 스킨답서스','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FSatin%20Pothos.webp?alt=media&token=181c8f10-9cee-4b37-9122-a7e876d3dd47','은빛 무늬가 매력적인 덩굴성 식물로, 일산화탄소 제거 능력이 우수합니다.','1~2년 주기 (봄 또는 초여름에 권장)',NULL,'반양지 또는 반음지 (너무 강한 직사광선은 은빛 무늬를 태울 수 있음)','겉흙이 말랐을 때 듬뿍 (과습에 주의하며 잎이 약간 처질 때가 적기입니다)'),(2,'필로덴드론 버킨','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FPhilodendron%20Birkin.jfif?alt=media&token=8f8cd942-306b-47a1-b147-0f578add2deb','흰색 줄무늬가 화려하게 퍼지는 고급스러운 느낌의 실내 관엽식물입니다.','2년 주기 (뿌리가 화분 아래로 나올 때)',NULL,'반양지 (빛을 충분히 받아야 흰색 무늬가 선명해집니다)','겉흙이 마르고 1~2일 뒤 듬뿍 (고온다습한 환경을 좋아함)'),(3,'인도고무나무','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FFicus%20elastica.jpg?alt=media&token=19d693ee-44b8-4c2c-80dd-d96e67ce3553','넓고 광택 있는 잎이 특징이며 미세먼지 흡착 능력이 뛰어난 대형 식물입니다.','2~3년 주기 (성장이 빠르므로 화분 크기를 키워주세요)',NULL,'양지 또는 반양지 (빛이 부족하면 잎의 광택이 사라집니다)','겉흙이 말랐을 때 듬뿍 (겨울에는 속흙까지 말랐을 때)'),(4,'홍콩야자','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FSchefflera%20arboricola.jfif?alt=media&token=93b41504-b56c-4b21-9464-8a023b8676c6','우산 모양으로 잎이 모여 나는 귀여운 식물로, 천연 가습기 역할을 합니다.','1~2년 주기 (성장이 매우 빠르므로 봄에 분갈이)',NULL,'반양지 (밝은 곳을 좋아하지만 직사광선은 피해주세요)','겉흙이 말랐을 때 듬뿍 (공중 분무를 자주 해주면 좋아합니다)'),(5,'여인초','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FStrelitzia%20nicolai.jfif?alt=media&token=1cb53e9c-309e-4b91-9576-83fb3f3b2472','시원하게 뻗은 넓은 잎이 매력적인 플랜테리어의 대표 식물입니다.','1~2년 주기 (뿌리가 굵어 화분을 깨뜨릴 수 있으니 주의)',NULL,'양지 또는 반양지 (빛이 충분해야 줄기가 튼튼하게 곧게 섭니다)','겉흙이 말랐을 때 화분 구멍으로 물이 나올 정도로 듬뿍'),(6,'스투키','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FSansevieria%20cylindrica.jfif?alt=media&token=b3fa880f-d643-4ab1-93b3-da3458df2028','밤에 산소를 배출하고 음이온을 생성하는 대표적인 공기정화 식물입니다.','2~3년 주기 (성장이 느려 화분이 꽉 찼을 때)',NULL,'반양지 또는 밝은 그늘 (직사광선은 잎을 타게 할 수 있음)','한 달에 1번 듬뿍 (속흙까지 바짝 말랐을 때)'),(7,'알로에 베라','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FAloe%20vera%20plant.webp?alt=media&token=1514af9a-aab1-4a3b-a07e-240d21f57dfb','피부 진정 효과와 수분 공급에 탁월하며 관리가 쉬운 약용 식물입니다.','2년 주기 (뿌리가 화분 밖으로 나올 때)',NULL,'양지 (햇빛을 매우 좋아하며 하루 4시간 이상 직사광선 권장)','3~4주에 1번 (잎이 약간 말랑해지거나 얇아졌을 때)'),(8,'염좌','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FCrassula%20ovata.jpg?alt=media&token=5bf6de5c-0357-4451-92d2-31c83db9f50d','돈을 부르는 나무로 불리며, 잎이 동전처럼 동글동글한 다육식물입니다.','3~4년 주기 (분갈이 스트레스에 민감하므로 천천히)',NULL,'양지 (빛을 많이 받을수록 잎 끝이 붉게 물들어 예쁩니다)','2~3주에 1번 (잎에 주름이 생기기 시작할 때 듬뿍)'),(9,'에케베리아','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FEcheveria%20succulent.jpg?alt=media&token=eba54800-e9f4-4608-a2e9-cf6f5aed152e','장미꽃 모양의 화려한 로제트를 가진 가장 인기 있는 다육 식물입니다.','1~2년 주기 (오래된 흙을 갈아주어 영양 공급)',NULL,'양지 (빛이 부족하면 모양이 망가지고 웃자라기 쉽습니다)','2주에 1번 (잎 사이에 물이 고이지 않게 저면관수 추천)'),(10,'십이지권','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FHaworthia%20attenuata.jpg?alt=media&token=efaae7eb-ffa4-49cd-b0c8-5da49d85c6dd','하얀 줄무늬가 층층이 쌓인 모습이 아름다운 작고 단단한 다육식물입니다.','3~4년 주기 (성장이 매우 느려 자주 할 필요 없음)',NULL,'반양지 (밝은 창가 안쪽이 가장 적합합니다)','3~4주에 1번 (잎이 오므라드는 느낌이 들 때 듬뿍)'),(11,'게발선인장','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FSchlumbergera.webp?alt=media&token=e1efb355-207f-4036-b616-7797f972c956','겨울에 화려한 꽃을 피워 크리스마스 선인장으로도 불리는 식물입니다.','1~2년 주기 (꽃이 진 직후인 봄에 권장)',NULL,'반양지 (통풍이 잘되는 창가 쪽이 가장 좋습니다)','겉흙이 말랐을 때 (꽃이 피는 시기에는 조금 더 자주)'),(12,'꽃기린','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FEuphorbia%20milii.webp?alt=media&token=0726a33f-c85b-4514-adf4-bafc4f182455','가시 돋친 줄기 끝에 작고 앙증맞은 꽃이 사계절 내내 피는 강인한 식물입니다.','2년 주기 (봄철에 배수가 잘되는 흙으로 교체)',NULL,'양지 (빛을 아주 좋아하며 햇빛이 많을수록 꽃 색이 진해집니다)','속흙까지 말랐을 때 듬뿍 (과습 시 잎이 우수수 떨어질 수 있음)'),(13,'아스플레니움 니두스','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FAsplenium%20nidus.webp?alt=media&token=87f85730-27bc-4f02-9742-d12e290c67a0','물결 모양의 연녹색 잎이 새둥지처럼 펼쳐지는 싱그러운 고사리 식물입니다.','1~2년 주기 (뿌리가 예민하므로 분갈이 시 주의)',NULL,'반음지 (직사광선에 매우 약하며 습도가 높은 곳을 좋아함)','겉흙이 촉촉하게 유지 (잎 가운데 성장점에 물이 고이지 않게 주의)'),(14,'필레아 페페','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FPilea%20peperomioides.jfif?alt=media&token=c9c2769a-04f0-4362-9f79-5d3a4d6a591c','동그란 동전 모양의 잎이 매력적이며 번식이 매우 쉬운 식물입니다.','1년 주기 (성장이 빠르므로 매년 봄에 권장)',NULL,'반양지 (직사광선보다는 밝은 창가 쪽)','겉흙이 마르고 1~2일 뒤 (잎이 약간 아래로 처질 때)'),(15,'마란타','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FMaranta%20leuconeura.webp?alt=media&token=9057ec43-29c0-444b-bc83-f2eb03fd0688','밤에 잎을 세워 모으는 모습이 기도하는 것 같아 기도하는 식물이라 불립니다.','1~2년 주기 (배수가 잘되는 흙 사용)',NULL,'반양지 또는 반음지 (빛이 너무 강하면 잎의 무늬가 흐려짐)','겉흙이 마르면 즉시 듬뿍 (공중 습도를 높게 유지해 주세요)'),(16,'칼라테아 오르비폴리아','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FCalathea%20orbifolia.webp?alt=media&token=ae87f03d-0f34-4358-8590-d1f7e85bdf75','넓은 원형 잎에 정교한 은색 줄무늬가 있어 살아있는 예술품이라 불리는 식물입니다.','2년 주기 (봄에 흙을 전체적으로 교체)',NULL,'반음지 (직사광선을 피하고 통풍이 잘되는 밝은 실내)','겉흙이 마르기 시작할 때 듬뿍 (수돗물의 염소 성분에 민감함)'),(17,'피토니아','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FFittonia.webp?alt=media&token=1d3928ce-66bc-4712-80ea-de2118d4cd11','화려한 잎맥 무늬가 특징이며 습도를 좋아하는 아기자기한 식물입니다.','1~2년 주기 (작은 화분에서 키우는 맛이 있는 식물)',NULL,'반음지 (습도가 높은 욕실이나 테라리움에서도 잘 자람)','겉흙이 마르면 듬뿍 (물이 부족하면 잎이 팍 시듭니다)'),(18,'바질','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FBasil%20plant.jpg?alt=media&token=73c5c951-8312-46b9-9411-466a01d378a4','향긋한 향으로 요리에 활용도가 높으며 키우는 재미가 있는 허브입니다.','1년 주기 (뿌리가 금방 화분을 채우므로 자주 체크)',NULL,'양지 (하루 최소 6시간 이상의 충분한 햇빛 필수)','겉흙이 마르면 즉시 듬뿍 (물을 매우 좋아하며 마르면 금방 시듭니다)'),(19,'로즈마리','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FRosemary%20plant.jfif?alt=media&token=36e6f0a5-15fa-42e7-b365-ecc44e5c48f8','강한 향이 뇌를 자극해 집중력 향상에 도움을 주는 기능성 허브입니다.','1~2년 주기 (분갈이 시 뿌리를 너무 많이 건드리지 마세요)',NULL,'양지 (직사광선과 통풍이 가장 중요한 핵심입니다)','겉흙이 마르면 듬뿍 (배수가 잘되는 흙이 필수이며 과습 주의)'),(20,'민트','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FMint%20plant.jfif?alt=media&token=e25e639f-baab-41b5-bdb1-5cf20527ffbe','싱그러운 향과 함께 성장이 매우 빠르고 생명력이 강한 식물입니다.','6개월~1년 주기 (뿌리 번식이 엄청나므로 금방 큰 화분이 필요함)',NULL,'양지 또는 반양지 (통풍이 잘되는 곳)','매일 혹은 이틀에 한 번 (흙을 항상 촉촉하게 유지)'),(21,'방울토마토','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FCherry%20tomato%20plant.jpg?alt=media&token=8663a511-7cfa-4840-9cc6-069dec497722','스마트팜이나 베란다에서 키워 수확의 기쁨을 느낄 수 있는 열매 작물입니다.','정식 시 대형 화분 사용 (분갈이보다 처음부터 큰 곳에 심기)',NULL,'양지 (햇빛이 부족하면 열매가 열리지 않습니다)','매일 아침 1번 (열매가 맺힐 때는 물이 마르지 않게 주의)'),(22,'라벤더','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2FLavender%20plant.webp?alt=media&token=dd2a708c-e2d1-4a13-b165-93ee6da5b0a6','심신 안정에 도움을 주는 향기로운 허브로, 보라색 꽃이 아름답습니다.','1~2년 주기 (뿌리가 발달하므로 넉넉한 화분 추천)',NULL,'양지 (하루 6시간 이상의 강한 햇빛과 원활한 통풍 필수)','겉흙이 바짝 말랐을 때 듬뿍 (과습은 절대 금물)'),(30001,'호랑이알로에','https://firebasestorage.googleapis.com/v0/b/smartfarm-2ba53.firebasestorage.app/o/plants%2F%ED%98%B8%EB%9E%91%EC%9D%B4%EC%95%8C%EB%A1%9C%EC%97%90.jfif?alt=media&token=a3a66334-a10c-48a4-b867-c5d680044db4','잎에 호랑이 무늬가 있어 관상 가치가 높은 단단한 알로에 종입니다.','2~3년 주기 (자구가 생기면 포기 나누기 진행)',NULL,'양지 또는 반양지 (통풍이 잘되는 곳을 선호)','4주에 1번 (겨울철에는 거의 주지 않아도 무방)');
/*!40000 ALTER TABLE `custom_dictionary` ENABLE KEYS */;
UNLOCK TABLES;

