CREATE TABLE `diary` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` varchar(50) DEFAULT NULL COMMENT '사용자 아이디',
  `title` varchar(255) DEFAULT NULL COMMENT '일기 제목',
  `content` text DEFAULT NULL COMMENT '일기 내용',
  `image_url` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '작성 시간',
  `date` varchar(255) DEFAULT NULL,
  `folder_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=510001;
/*!40101 SET character_set_client = @saved_cs_client */;

